  // About page
  aboutTitle: "À propos de DLXSTORE",
  aboutDescription: "DLXSTORE est la plateforme e-commerce de référence pour la ville de Goma. Nous simplifions vos achats quotidiens en combinant un catalogue premium, une livraison ultra-rapide et un paiement cash sécurisé à votre porte.",
  aboutFounders: "Les fondateurs",
  aboutFoundersDescription: "DLXSTORE est porté par Agassi David Akilimali et Kengamungu Benjamin. Ils développent une plateforme de marché pensée pour servir les clients, vendeurs et partenaires de Goma avec sérieux et transparence.",
  aboutMission: "Notre Mission",
  aboutMissionDescription1: "Nous croyons que chaque habitant de Goma mérite une expérience d'achat moderne et sans friction. Finis les tracas des marchés bondés ou l'insécurité des paiements en ligne non réglementés. Avec DLXSTORE, commandez en un clic, inspectez vos articles à la livraison et payez uniquement si vous êtes convaincu.",
  aboutMissionDescription2: "Qu'il s'agisse de s'équiper en énergie solaire pour faire face aux délestages réguliers, de s'offrir le dernier smartphone ou d'acheter du café arabica produit localement, DLXSTORE est là pour vous servir.",
  aboutCommitments: "Nos Engagements Majeurs",
  aboutCommitment1: "Livraison Gratuite",
  aboutCommitment1Desc: "Nous livrons gratuitement sur toute l'étendue de Goma (Himbi, Keshero, Katindo, Ndosho, etc.) sans aucun montant minimum d'achat requis.",
  aboutCommitment2: "Paiement sur Livraison",
  aboutCommitment2Desc: "Cash on Delivery (COD) uniquement. Nous ne vous demandons jamais vos coordonnées bancaires en ligne. Vous payez en espèces après vérification.",
  aboutCommitment3: "Originalité Garantie",
  aboutCommitment3Desc: "Tous nos articles (sneakers, ordinateurs, stations de recharge solaires) proviennent de sources vérifiées et d'une authenticité certifiée.",
  aboutCTATitle: "Prêt à faire des achats intelligents ?",
  aboutCTADescription: "Découvrez dès maintenant notre catalogue d'articles originaux disponibles pour Goma.",
  aboutCTAButton: "Visiter la boutique",

// Home FAQ
  faq1Q: "Comment fonctionne la livraison gratuite à Goma ?",
  faq1A: "La livraison est 100% gratuite dans tous les quartiers de Goma (Himbi, Keshero, Katindo, Ndosho, Mugunga, Majengo, Mabanga, Bujovu, etc.). Une fois votre commande passée, un livreur vous contactera par téléphone pour convenir de l'heure exacte de livraison.",
  faq2Q: "Comment puis-je payer mes articles ?",
  faq2A: "Chez DLXSTORE, nous utilisons exclusivement le paiement à la livraison (Cash on Delivery). Vous payez en dollars américains (USD) ou en francs congolais (CDF) directement au livreur, après avoir vérifié et essayé vos produits.",
  faq3Q: "Comment contacter DLXSTORE ?",
  faq3A: "Les canaux officiels de DLXSTORE sont publiés dans la page Contact dès qu'ils sont configurés par l'équipe.",
  faq4Q: "Que faire si un article ne me convient pas ?",
  faq4A: "Vous pouvez refuser l'article directement auprès du livreur lors de la présentation. Consultez la page Contact pour les canaux de support officiels.",
  testimonial1Role: "Entrepreneuse, Keshero",
  testimonial1Text: "J'ai acheté la station solaire EcoFlow pour ma boutique. La livraison était totalement gratuite jusqu'à ma porte et j'ai payé en espèces après avoir testé l'appareil. Un service de confiance rare à Goma !",
  testimonial2Role: "Étudiant, Himbi",
  testimonial2Text: "Le MacBook Air est arrivé scellé et en parfait état. Le fait de pouvoir vérifier la marchandise avant de donner l'argent au livreur rassure énormément. Je recommande DLXSTORE à 100%.",
  testimonial3Role: "Enseignant, Ndosho",
  testimonial3Text: "La livraison à Ndosho s'est faite le jour même de la commande. Les baskets Nike sont originales et très confortables pour mes déplacements quotidiens.",
