  // About page
  aboutTitle: "About DLXSTORE",
  aboutDescription: "DLXSTORE is the reference e-commerce platform for the city of Goma. We simplify your daily shopping by combining a premium catalog, ultra-fast delivery, and secure cash payment at your door.",
  aboutFounders: "The Founders",
  aboutFoundersDescription: "DLXSTORE is led by Agassi David Akilimali and Kengamungu Benjamin. They are developing a marketplace platform designed to serve Goma's customers, sellers, and partners with seriousness and transparency.",
  aboutMission: "Our Mission",
  aboutMissionDescription1: "We believe every Goma resident deserves a modern, friction-free shopping experience. No more crowded market hassles or unregulated online payment insecurity. With DLXSTORE, order with one click, inspect items on delivery, and pay only if you're convinced.",
  aboutMissionDescription2: "Whether equipping with solar energy to handle regular power cuts, getting the latest smartphone, or buying locally produced arabica coffee, DLXSTORE is here to serve you.",
  aboutCommitments: "Our Major Commitments",
  aboutCommitment1: "Free Delivery",
  aboutCommitment1Desc: "We deliver free across the entire extent of Goma (Himbi, Keshero, Katindo, Ndosho, etc.) with no minimum purchase amount required.",
  aboutCommitment2: "Payment on Delivery",
  aboutCommitment2Desc: "Cash on Delivery (COD) only. We never ask for your banking details online. You pay in cash after verification.",
  aboutCommitment3: "Authenticity Guarantee",
  aboutCommitment3Desc: "All our items (sneakers, computers, solar charging stations) come from verified sources with certified authenticity.",
  aboutCTATitle: "Ready to shop smart?",
  aboutCTADescription: "Discover our catalog of original items available for Goma right now.",
  aboutCTAButton: "Visit the shop",

// Home FAQ
  faq1Q: "How does free delivery in Goma work?",
  faq1A: "Delivery is 100% free in all Goma neighbourhoods (Himbi, Keshero, Katindo, Ndosho, Mugunga, Majengo, Mabanga, Bujovu, etc.). Once your order is placed, a courier will call you to arrange the exact delivery time.",
  faq2Q: "How can I pay for my items?",
  faq2A: "At DLXSTORE we use Cash on Delivery only. You pay in US dollars (USD) or Congolese francs (CDF) directly to the courier, after checking and trying your products.",
  faq3Q: "How do I contact DLXSTORE?",
  faq3A: "Official DLXSTORE channels are published on the Contact page as soon as they are set up by the team.",
  faq4Q: "What if an item does not suit me?",
  faq4A: "You can refuse the item directly with the courier when it is presented. Check the Contact page for official support channels.",
  testimonial1Role: "Entrepreneur, Keshero",
  testimonial1Text: "I bought the EcoFlow solar station for my shop. Delivery was completely free to my door and I paid in cash after testing the device. A service you can trust, rare in Goma!",
  testimonial2Role: "Student, Himbi",
  testimonial2Text: "The MacBook Air arrived sealed and in perfect condition. Being able to check the product before giving money to the courier is very reassuring. I recommend DLXSTORE 100%.",
  testimonial3Role: "Teacher, Ndosho",
  testimonial3Text: "Delivery to Ndosho was done the same day I ordered. The Nike sneakers are original and very comfortable for my daily commute.",
