  // About page
  aboutTitle: "Kuhusu DLXSTORE",
  aboutDescription: "DLXSTORE ni jukwaa la rejeleo kwa e-commerce kwa jiji la Goma. Tunarahisisha ununuzo wako wa kila siku kwa kuunganisha katalogi ya premium, usafiri wa haraka na malipo ya fedha salama kwenye mlango wako.",
  aboutFounders: "Waanzilishi",
  aboutFoundersDescription: "DLXSTORE inaongozwa na Agassi David Akilimali na Kengamungu Benjamin. Wanatengeneza jukwaa la soko lililounda kuwatumia wateja, wauzaji na washirika wa Goma kwa uzalendo na uwazi.",
  aboutMission: "Dhamira Yetu",
  aboutMissionDescription1: "Tunaamini kila mkazi wa Goma anastahali uzoefu wa kununua wa kisasa bila changamoto. Hakuna changamoto za soko zilizojaa au usalama wa malipo ya mtandaoni ambayo haitawala. Na DLXSTORE, nunua kwa kugota moja, angalia bidhaa kwenye usafiri na lipa kama unaidhinishwa.",
  aboutMissionDescription2: "Kama ni kujiweka na nishati ya jua kukabiliana na kukatika kwa umeme, kupata simu mpya ya kisasa au kununua kahawa ya arabica iliyotengenezwa ndani, DLXSTORE ipo hapa kukutumikia.",
  aboutCommitments: "Uwajibikaji Wetu Wakubwa",
  aboutCommitment1: "Usafiri wa Bure",
  aboutCommitment1Desc: "Tunakabari bure katika eneo zote za Goma (Himbi, Keshero, Katindo, Ndosho, nk.) bila kiwango cha chini cha ununuzo kinachohitajika.",
  aboutCommitment2: "Lipa Kwenye Usafiri",
  aboutCommitment2Desc: "Cash on Delivery (COD) tu. Hatutauli kamwi tete ya benki mtandaoni. Unalipa kwa pesa taslimu baada ya kuthibitisha.",
  aboutCommitment3: "Dhamana ya Asili",
  aboutCommitment3Desc: "Bidhaa zetu zote (sneakers, kompyuta, vituo vya chaji ya jua) zinatoka chanzo zilizothibitishwa na uhakika wa asili.",
  aboutCTATitle: "Je tayari kununua kwa akili?",
  aboutCTADescription: "Gundua katalogi yetu ya bidhaa za asili zinazopatikana kwa Goma sasa hivi.",
  aboutCTAButton: "Tembelea duka",
