// Home FAQ
  faq1Q: "Usafiri wa bure Goma unafanyaje kazi?",
  faq1A: "Usafiri ni bure 100% katika mitaa yote ya Goma (Himbi, Keshero, Katindo, Ndosho, Mugunga, Majengo, Mabanga, Bujovu, n.k.). Baada ya kuweka oda yako, msafirishaji atakupigia simu kupanga saa halisi ya utoaji.",
  faq2Q: "Ninawezaje kulipia bidhaa zangu?",
  faq2A: "Katika DLXSTORE tunatumia malipo kwa utoaji pekee. Unalipa kwa dola za Marekani (USD) au faranga za Kongo (CDF) moja kwa moja kwa msafirishaji, baada ya kukagua na kujaribu bidhaa zako.",
  faq3Q: "Ninawezaje kuwasiliana na DLXSTORE?",
  faq3A: "Njia rasmi za DLXSTORE zinachapishwa kwenye ukurasa wa Wasiliana mara tu timu itakapozisakinisha.",
  faq4Q: "Nifanye nini kama bidhaa haifai?",
  faq4A: "Unaweza kukataa bidhaa moja kwa moja kwa msafirishaji anapoileta. Angalia ukurasa wa Wasiliana kwa njia rasmi za usaidizi.",
  testimonial1Role: "Mfanyabiashara, Keshero",
  testimonial1Text: "Nilinunua kituo cha jua cha EcoFlow kwa duka langu. Usafiri ulikuwa bure kabisa hadi mlangoni mwangu na nililipa kwa pesa taslimu baada ya kujaribu kifaa. Huduma ya kuaminika, nadra Goma!",
  testimonial2Role: "Mwanafunzi, Himbi",
  testimonial2Text: "MacBook Air ilifika imefungwa na katika hali nzuri. Kuweza kukagua bidhaa kabla ya kumpa pesa msafirishaji kunatia raha sana. Ninapendekeza DLXSTORE 100%.",
  testimonial3Role: "Mwalimu, Ndosho",
  testimonial3Text: "Usafiri wa Ndosho ulifanyika siku hiyo hiyo nilipoagiza. Viatu vya Nike ni halisi na vizuri sana kwa matembezi yangu ya kila siku.",
