  // About page
  aboutTitle: "Mokandá wa DLXSTORE",
  aboutDescription: "DLXSTORE ezalí platefɔ́rɛ ya commerce électronique ya référence mpo na ville ya Goma. Tokomisa basala ya bilɔ́mbɔ ya nyɔn na kobɔ́ngɔ́ katalogu ya premium, kotámbisa ya rápi mpe mfutu ya mbongo ya cash na kɔ́ntɔ ya nyɔn.",
  aboutFounders: "Bakwéli",
  aboutFoundersDescription: "DLXSTORE ezalí endimɛ́ na Agassi David Akilimali mpe Kengamungu Benjamin. Bakokómba platefɔ́rɛ ya soko esálámí mpo na kotámbisa bakonzi, ba vendeurs mpe ba partenaires ya Goma na sérieux mpe transparence.",
  aboutMission: "Mission ya Bisu",
  aboutMissionDescription1: "Tokokámbɔ́ que chaque mokɔ́mbɔ ya Goma azalí kobɔ́ngɔ́ expérience ya kɔ́tɔ́ bilɔ́mbɔ ya moderno sans friction. Fini makambo ya marché ya bondé tɛ́ óyo insecurity ya mbongo ya internet mpo kofungáma. Na DLXSTORE, sála magɛngɛ na kogóta moja, kokota bilɔ́mbɔ ya nyɔn na kotámbisa kaka si ozalí convaincu.",
  aboutMissionDescription2: "Soki kɔ́tɔ́ ya sɔ́kɔ́ énergie solaire mpo na kobɔ́ngɔ́ délestage ya régulier, ya kobɔ́ngɔ́ smartphone ya sika tɛ́ ya kununua café arabica produit localement, DLXSTORE azalí epɔ́ni mpo na kotámbisa nyɔn.",
  aboutCommitments: "Engagements Majeurs ya Bisu",
  aboutCommitment1: "Kotámbisa ya Bure",
  aboutCommitment1Desc: "Tokotámbisa burre na bilingi ya Goma (Himbi, Keshero, Katindo, Ndosho, nk.) sans montant minimum ya magɛngɛ obosɛléngélémí.",
  aboutCommitment2: "Mfutu na Kotámbisa",
  aboutCommitment2Desc: "Cash on Delivery (COD) kaka. Tokosɔ́ngɔ́ jamais tɛ́ coordonnées bancaire ya nyɔn na internet. Ozalipa kwa mbongo ya cash baada ya kokota.",
  aboutCommitment3: "Authenticité Garantie",
  aboutCommitment3Desc: "Bilɔ́mbɔ nyɔ́nsɔ (sneakers, ordinateurs, stations ya recharge solaire) ezalí na sources vérifiées mpe authenticité certifiée.",
  aboutCTATitle: "Prêt à sála magɛngɛ ya akili ?",
  aboutCTADescription: "Tála katalogu ya bilɔ́mbɔ ya original disponible mpo na Goma sika.",
