// Home FAQ
  faq1Q: "Kotámbisa ya pámba na Goma esalaka ndé nini?",
  faq1A: "Kotámbisa ezalí 100% ya pámba na bilingi nyonso ya Goma (Himbi, Késhero, Katindo, Ndosho, Mugunga, Majengo, Mabanga, Bujovu, mpe b.). Soki odá na yo esílí, moto moko akobenga yo na telefóne mpo na koyókana ngonga ya kotámbisa.",
  faq2Q: "Nakofuta ndé nini biléi bya ngai?",
  faq2A: "Na DLXSTORE tosalaka kaka malipo na tango ya kotámbisa (COD). Ofutaka na dolare (USD) to na falánga ya Kongó (CDF) mbala moko epái ya moto ya kotámbisa, nsima ya komeka biléi bya yo.",
  faq3Q: "Kokutana ndé nini na DLXSTORE?",
  faq3A: "Banzela ya mokonzi ya DLXSTORE ebimisamaka na lokasá ya Contact tango kaka timu esílí kokokisa yango.",
  faq4Q: "Nasala nini soki elamba ebongi na ngai te?",
  faq4A: "Okoki koboya elamba mbala moko epái ya moto ya kotámbisa na tango akoyanola yango. Tála lokasá ya Contact mpo na banzela ya kosunga.",
  testimonial1Role: "Mobandisi, Keshero",
  testimonial1Text: "Nasómá station solaire ya EcoFlow mpo na magazini na ngai. Kotámbisa ezaláká ya pámba kino na mongó mpe nafutákí na mbongo nsima ya komeka esaleli. Mosálá ya kondima, ezalí moké na Goma!",
  testimonial2Role: "Moyékoli, Himbi",
  testimonial2Text: "MacBook Air eyaki ya kolámba mpe ya kitoko. Koyeba kokamba biléi libosó ya kopesa mbongo epái ya moto ya kotámbisa epesaka kimia mingi. Nalobelaka DLXSTORE na 100%.",
  testimonial3Role: "Molakisi, Ndosho",
  testimonial3Text: "Kotámbisa na Ndosho esalemaki mokolo yango moko oyo natómaki odá. Basapatu ya Nike ezalí ya solo mpe ya kitoko mingi mpo na kotambola na ngai ya mokolo na mokolo.",
