// Home FAQ
  faq1Q: "Kutambula kwa bule mu Goma kusakana neyi kuena?",
  faq1A: "Kutambula ni kwa bule 100% mu misumbu yawonso ya Goma (Himbi, Keshero, Katindo, Ndosho, Mugunga, Majengo, Mabanga, Bujovu, ni bikuabu). Mbayidila oda yenu, mufikishi wakubena mu telefone pa kusumangana tshikondo tsha kufikisa.",
  faq2Q: "Nsombwesha nyi madimi ami?",
  faq2A: "Mu DLXSTORE tunyongolanga kaka mfutu wa kufikisila (COD). Mubadika mu madala a Amerika (USD) ne mu mfuranse a Kongo (CDF) kudi mufikishi, kinyi kya kunyonga ne kuyesha bintu bienu.",
  faq3Q: "Kukuayana nyi na DLXSTORE?",
  faq3A: "Banzela bia mfunu bia DLXSTORE bionshekena mu peji ya Contact kinyi kya kubena biongo kusungika kudi kipangu.",
  faq4Q: "Nsala nyi nga kintu kikambawu?",
  faq4A: "Mukanka kintu kudi mufikishi pa kukufikisa. Tala peji ya Contact mu banzela bia lusadisu.",
  testimonial1Role: "Mfuanistsha, Keshero",
  testimonial1Text: "Nasumbila station ya divua ya EcoFlow mu shibinda dyami. Kutambula kwidi bule nakanyisha mu kibundi ni mfudile na mbongo kinyi kya kuyesha kintu. Kibo kia lusumbu, kidi kayi mu Goma!",
  testimonial2Role: "Mulongi, Himbi",
  testimonial2Text: "MacBook Air yafikile yidi ya kudibakila ya malu. Kubakula bintu kabidi kwa kupa mbongo kudi mufikishi kunesha lukulupilo. Nditshishila DLXSTORE pa 100%.",
  testimonial3Role: "Mulongeshi, Ndosho",
  testimonial3Text: "Kutambula ku Ndosho kwafikile mu difuku dinee dyenyi efile oda. Bisapatu bia Nike bidi bia kishilelu ne bidia mu lwendo lwami lwa kazuwa kazuwa.",
