export function translate(language: Language) {
  if (language === "fr") return fr;
  if (language === "en") return en;
  if (language === "sw") return sw;
  if (language === "ln") return ln;
  if (language === "tl") return tl;
  if (language === "kg") return kg;
  return en; // fallback to English
}

export type TranslationKeys = typeof fr;

/**
 * Fills `{placeholder}` tokens in a translated string.
 *
 * Kept separate from `translate` so the lookup table stays a flat string map —
 * which is what lets `TranslationKeys` be derived from it. Unknown placeholders
 * are left verbatim rather than blanked, so a missing value is visible during
 * development instead of silently producing "Delivered  of 5".
 */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) =>
    Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : match
  );
}